/** Keyed lookup, for the one-off render sites. */
export const MARK_BY_KEY: Record<string, ConsoleMark> = Object.fromEntries(
  CONSOLE_MARKS.map((m) => [m.key, m]),
);

/** The wall, in the demo's own order. Not simply "the ones with a label" —
 *  order is part of the design and a filter would not preserve it. */
export const WALL_MARKS: ConsoleMark[] = ["capsule","meal","glass","dumbbell","sauna","moon","cabin","care"].map(
  (k) => MARK_BY_KEY[k],
);
